  ('99439fa1-2554-59f2-a482-13434633b4ba', null, (select id from public.skills where slug = 'write-g10-sentence-structure'), null, 'hard',
   $q$Read the sentences: "The Silk Road was not a single road. It was a network of trade routes. These routes linked China with the Mediterranean." Which choice combines them most clearly and correctly?$q$, $q$[{"text":"Linking China with the Mediterranean, the Silk Road was not a single road, it was a network of trade routes.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"The Silk Road, not a single road but a network of trade routes linking China with the Mediterranean.","is_correct":false,"misconception_token":"appositive-fragment"},{"text":"The Silk Road was not a single road, it was a network of trade routes, these routes linked China with the Mediterranean.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"The Silk Road was not a single road but a network of trade routes linking China with the Mediterranean.","is_correct":true}]$q$::jsonb, $q$The Silk Road was not a single road but a network of trade routes linking China with the Mediterranean.$q$, $q$The "not... but" structure and the phrase "linking China with the Mediterranean" combine all three ideas around one main verb, "was." The version that sets everything off with commas after "The Silk Road" never gives the subject a verb, so it is a fragment.$q$, 'draft', null)
