  ('b825ab67-2da5-50a7-8cb5-ba5ae74aaf4e', null, (select id from public.skills where slug = 'write-g10-sentence-structure'), null, 'hard',
   $q$Which sentence is punctuated correctly?$q$, $q$[{"text":"The drought lasted three summers; because the reservoir was shallow.","is_correct":false,"misconception_token":"semicolon-before-dependent-clause"},{"text":"The drought lasted three summers; as a result, the reservoir dropped to record lows.","is_correct":true},{"text":"The drought lasted three summers, the reservoir dropped to record lows.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"The drought lasted three summers, as a result the reservoir dropped to record lows.","is_correct":false,"misconception_token":"conjunctive-adverb-with-comma-only"}]$q$::jsonb, $q$The drought lasted three summers; as a result, the reservoir dropped to record lows.$q$, $q$A semicolon joins the two independent clauses, and the transition "as a result" is followed by a comma. Putting only a comma before "as a result" still joins two independent clauses with a comma, which is a comma splice.$q$, 'draft', null)
