  ('e9b9bd5f-734e-5f80-875c-8fa38a64f5db', null, (select id from public.skills where slug = 'write-g10-sentence-structure'), null, 'hard',
   $q$Read the sentence: "The volunteers repaired the benches in the park that had been damaged by the winter storm." Which revision makes clear that the benches, not the whole park, had been damaged?$q$, $q$[{"text":"The volunteers repaired the park benches that had been damaged by the winter storm.","is_correct":true},{"text":"The volunteers, who had been damaged by the winter storm, repaired the benches in the park.","is_correct":false,"misconception_token":"misplaced-modifier"},{"text":"The volunteers repaired the benches in the park, that had been damaged by the winter storm.","is_correct":false,"misconception_token":"misplaced-modifier"},{"text":"In the park that had been damaged by the winter storm, the volunteers repaired the benches.","is_correct":false,"misconception_token":"misplaced-modifier"}]$q$::jsonb, $q$The volunteers repaired the park benches that had been damaged by the winter storm.$q$, $q$Making "park" an adjective in "park benches" puts the clause "that had been damaged" right after "benches," the word it describes. The version beginning "In the park that had been damaged" clearly says the park was damaged, not the benches.$q$, 'draft', null)
